export default async function charge({ env, ctx }: { env: Env; ctx: { attempt: number } }) {
  if (ctx.attempt > 2) throw new Error('Charge refused after retries')
  const response = await fetch('https://api.example.com/charges', {
    method: 'POST',
    headers: { Authorization: `Bearer ${env.CHARGE_TOKEN}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ amount: 4200 }),
  })
  if (!response.ok) throw new Error(`Charge failed: ${response.status}`)
  return { charged: true }
}

export default async function recover({ inputs }: { inputs: Record<string, unknown> }) {
  const error = inputs.error as { message?: string } | undefined
  return { recovered: true, reason: error?.message ?? 'unknown' }
}

export default async function cleanup() {
  return { cleaned: true }
}

export default async function report() {
  return { reported: true }
}
